from pathlib import Path
import re

path = Path('/home/ubuntu/pathfinder-ai/client/src/pages/Home.tsx')
s = path.read_text()

s = s.replace('ArrowRight, Bookmark, BriefcaseBusiness, Check, ChevronRight, CircleHelp, Compass, GraduationCap,', 'ArrowRight, Bookmark, BriefcaseBusiness, Check, ChevronLeft, ChevronRight, CircleHelp, Compass, GraduationCap,')

s = s.replace('const applicationList = trpc.applications.list.useQuery(undefined, { enabled: isAuthenticated }); const pathwayList', 'const applicationList = trpc.applications.list.useQuery(undefined, { enabled: isAuthenticated }); const [calendarMonth, setCalendarMonth] = useState(() => { const now = new Date(); return new Date(now.getFullYear(), now.getMonth(), 1); }); const calendarRange = useMemo(() => { const from = new Date(calendarMonth.getFullYear(), calendarMonth.getMonth(), 1); const to = new Date(calendarMonth.getFullYear(), calendarMonth.getMonth() + 1, 1); return { from, to }; }, [calendarMonth]); const deadlineQuery = trpc.applications.deadlines.useQuery(calendarRange, { enabled: isAuthenticated }); const upcomingDeadlineQuery = trpc.applications.upcoming.useQuery(undefined, { enabled: isAuthenticated }); const pathwayList')
s = s.replace('const createApplication = trpc.applications.create.useMutation(); const updateApplication = trpc.applications.update.useMutation(); const generateDraft', 'const createApplication = trpc.applications.create.useMutation(); const updateApplication = trpc.applications.update.useMutation(); const removeApplication = trpc.applications.remove.useMutation(); const generateDraft')
s = s.replace('setApplications(applicationList.data.map(item => ({ id: item.id, title: item.title, org: item.organisation, type: item.type, deadline: item.deadlineDate ? new Date(item.deadlineDate).toLocaleDateString() : "No deadline", status: item.status, dateApplied: item.dateApplied ? new Date(item.dateApplied).toLocaleDateString() : undefined, notes: item.notes || undefined })))', 'setApplications(applicationList.data.map(item => ({ id: item.id, title: item.title, org: item.organisation, type: item.type, deadlineDate: item.deadlineDate ? new Date(item.deadlineDate).toISOString() : null, deadline: item.deadlineDate ? new Date(item.deadlineDate).toLocaleDateString() : "No deadline", status: item.status, dateApplied: item.dateApplied ? new Date(item.dateApplied).toLocaleDateString() : undefined, notes: item.notes || undefined })))')
s = s.replace('onView={setView} profileComplete={profileComplete} onStart={() => setProfileOpen(true)} />', 'onView={setView} profileComplete={profileComplete} onStart={() => setProfileOpen(true)} upcomingDeadlines={upcomingDeadlineQuery.data || []} />')

old_app = re.search(r'function Applications\b.*?(?=\nfunction Stat)', s, re.S)
if not old_app:
    old_app = re.search(r'function Applications\b.*?(?=function Stat)', s, re.S)
if not old_app:
    raise SystemExit('Applications function not found')

new_app = r'''function Applications({ applications, setApplications, deadlineItems, visibleMonth, onMonthChange, onEditApplication, onUpdateStatus, onSaveApplication, onRemoveApplication, onGenerateDraft }: { applications: { id?: number; title: string; org: string; type: string; deadline: string; deadlineDate?: string | null; status: string; dateApplied?: string; notes?: string }[]; setApplications: React.Dispatch<React.SetStateAction<any[]>>; deadlineItems: any[]; visibleMonth: Date; onMonthChange: (month: Date) => void; onEditApplication: (index: number, form: any) => Promise<void>; onUpdateStatus: (item: any, status: string) => Promise<void>; onSaveApplication: (form: { title: string; organisation: string; type: "Study" | "Work" | "Skills" | "Business" | "Other"; dateApplied?: Date; deadlineDate?: Date; status?: "Not started" | "Applied" | "Interview" | "Waiting" | "Accepted" | "Not this time" | "Withdrawn"; notes?: string }) => Promise<void>; onRemoveApplication: (item: any) => Promise<void>; onGenerateDraft: (selectedIndex: number) => Promise<string> }) {
  const [draftOpen, setDraftOpen] = useState(false); const [editingIndex, setEditingIndex] = useState<number | null>(null); const [editorOpen, setEditorOpen] = useState(false); const [selectedIndex, setSelectedIndex] = useState(0); const [selectedDate, setSelectedDate] = useState<string | null>(null); const [calendar, setCalendar] = useState(true); const [form, setForm] = useState({ title: "", organisation: "", type: "Other", dateApplied: "", deadlineDate: "", status: "Not started", notes: "" }); const [draft, setDraft] = useState(`Hello, I’m a motivated learner exploring opportunities to grow my skills and contribute meaningfully.\n\nI’m interested in this opportunity because it connects with my strengths and the direction I’m building towards.\n\nKind regards,\n[Your name]`); const statuses = ["Not started", "Applied", "Interview", "Waiting", "Accepted", "Not this time"]; const inProgress = applications.filter(a => !["Accepted", "Not this time", "Withdrawn"].includes(a.status)).length; const upcoming = deadlineItems.length; const positive = applications.filter(a => a.status === "Accepted").length; const year = visibleMonth.getFullYear(); const month = visibleMonth.getMonth(); const daysInMonth = new Date(year, month + 1, 0).getDate(); const leading = (new Date(year, month, 1).getDay() + 6) % 7; const monthLabel = visibleMonth.toLocaleDateString(undefined, { month: "long", year: "numeric" }); const dateKey = (value: any) => { const date = new Date(value); return Number.isNaN(date.getTime()) ? null : `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`; }; const itemsByDay = new Map<string, any[]>(); deadlineItems.forEach(item => { const key = dateKey(item.deadlineDate); if (key) itemsByDay.set(key, [...(itemsByDay.get(key) || []), item]); }); const selectedItems = selectedDate ? (itemsByDay.get(selectedDate) || []) : []; const changeMonth = (delta: number) => { onMonthChange(new Date(year, month + delta, 1)); setSelectedDate(null); }; const jumpToday = () => { const now = new Date(); onMonthChange(new Date(now.getFullYear(), now.getMonth(), 1)); setSelectedDate(dateKey(now)); }; const copyDraft = async () => navigator.clipboard?.writeText(draft); const emailDraft = () => { window.location.href = `mailto:?subject=${encodeURIComponent("Application draft")}&body=${encodeURIComponent(draft)}`; }; return <div><div className="flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><Pill color="coral"><BriefcaseBusiness size={13} className="mr-1" /> Applications</Pill><h1 className="font-display mt-4 text-4xl tracking-[-.04em]">Keep your momentum<br /><span className="text-[#df6548]">in one place.</span></h1><p className="mt-3 text-[#6c8490]">Track deadlines, notice progress, and turn each application into a next move.</p></div><Button onClick={() => { setEditingIndex(null); setForm({ title: "", organisation: "", type: "Other", dateApplied: "", deadlineDate: "", status: "Not started", notes: "" }); setEditorOpen(true); }}>Add application <ArrowRight size={16} /></Button></div><div className="mt-8 grid gap-4 sm:grid-cols-3"><Stat label="In progress" value={inProgress} tone="blue" /><Stat label="Upcoming deadlines" value={upcoming} tone="coral" /><Stat label="Positive outcomes" value={positive} tone="green" /></div><div className="mt-8 flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-[#8aa0a8]">Your deadlines</p><h2 className="font-display mt-2 text-3xl tracking-[-.03em]">A calendar you can act on.</h2></div><Button variant="outline" onClick={() => setCalendar(!calendar)}>{calendar ? "Hide calendar" : "Show calendar"}</Button></div>{calendar && <div className="mt-5 rounded-[24px] bg-white p-5 card-border sm:p-6"><div className="flex flex-wrap items-center justify-between gap-3"><div className="flex items-center gap-2"><button aria-label="Previous month" onClick={() => changeMonth(-1)} className="flex h-10 w-10 items-center justify-center rounded-full border border-[#dce9ea] text-[#52717d] hover:border-[#0d9488]"><ChevronLeft size={17} /></button><button aria-label="Next month" onClick={() => changeMonth(1)} className="flex h-10 w-10 items-center justify-center rounded-full border border-[#dce9ea] text-[#52717d] hover:border-[#0d9488]"><ChevronRight size={17} /></button><h3 className="min-w-[145px] text-lg font-bold text-[#183b56]">{monthLabel}</h3></div><div className="flex items-center gap-2"><select aria-label="Month" value={month} onChange={e => onMonthChange(new Date(year, Number(e.target.value), 1))} className="h-10 rounded-xl border border-[#dce9ea] bg-white px-2 text-sm"><option value={0}>January</option><option value={1}>February</option><option value={2}>March</option><option value={3}>April</option><option value={4}>May</option><option value={5}>June</option><option value={6}>July</option><option value={7}>August</option><option value={8}>September</option><option value={9}>October</option><option value={10}>November</option><option value={11}>December</option></select><select aria-label="Year" value={year} onChange={e => onMonthChange(new Date(Number(e.target.value), month, 1))} className="h-10 rounded-xl border border-[#dce9ea] bg-white px-2 text-sm">{Array.from({ length: 16 }, (_, i) => year - 5 + i).map(value => <option key={value}>{value}</option>)}</select><button onClick={jumpToday} className="h-10 rounded-xl bg-[#e8f6f3] px-3 text-xs font-bold text-[#0f766e]">Today</button></div></div><div className="mt-5 grid grid-cols-7 gap-2 text-center text-xs"><span className="p-2 font-bold text-[#8aa0a8]">M</span><span className="p-2 font-bold text-[#8aa0a8]">T</span><span className="p-2 font-bold text-[#8aa0a8]">W</span><span className="p-2 font-bold text-[#8aa0a8]">T</span><span className="p-2 font-bold text-[#8aa0a8]">F</span><span className="p-2 font-bold text-[#8aa0a8]">S</span><span className="p-2 font-bold text-[#8aa0a8]">S</span>{Array.from({ length: leading }, (_, i) => <span key={`blank-${i}`} />)}{Array.from({ length: daysInMonth }, (_, i) => { const day = i + 1; const key = `${year}-${String(month + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}`; const items = itemsByDay.get(key) || []; const hasAccepted = items.some(item => item.status === "Accepted"); const isSelected = selectedDate === key; return <button key={key} onClick={() => setSelectedDate(key)} className={`min-h-14 rounded-xl p-2 text-left transition ${isSelected ? "ring-2 ring-[#0d9488]" : ""} ${items.length ? hasAccepted ? "bg-[#e7f8eb] font-bold text-[#258044]" : "bg-[#fff0ea] font-bold text-[#d95d3f]" : "bg-[#f7fafc] text-[#52717d]"}`}><span>{day}</span>{items.length > 0 && <span className={`mx-auto mt-1 block h-1.5 w-1.5 rounded-full ${hasAccepted ? "bg-[#258044]" : "bg-[#ff7a59]"}`} />}</button>; })}</div>{selectedDate && <div className="mt-5 rounded-2xl bg-[#fffaf7] p-4"><div className="flex items-center justify-between"><strong className="text-[#183b56]">Due {new Date(`${selectedDate}T12:00:00`).toLocaleDateString(undefined, { month: "long", day: "numeric", year: "numeric" })}</strong><span className="text-xs font-bold text-[#8aa0a8]">{selectedItems.length} item{selectedItems.length === 1 ? "" : "s"}</span></div>{selectedItems.length ? <div className="mt-3 overflow-hidden rounded-xl bg-white"><div className="hidden grid-cols-[1.2fr_.6fr_.7fr_.7fr] gap-3 border-b border-[#edf3f3] px-4 py-3 text-[10px] font-bold uppercase tracking-[.12em] text-[#8aa0a8] sm:grid"><span>Opportunity</span><span>Type</span><span>Deadline</span><span>Status</span></div>{selectedItems.map(item => <div key={item.id} className="grid gap-2 border-b border-[#edf3f3] px-4 py-3 last:border-0 sm:grid-cols-[1.2fr_.6fr_.7fr_.7fr] sm:items-center"><div><p className="text-sm font-bold text-[#183b56]">{item.title}</p><p className="text-xs text-[#8aa0a8]">{item.organisation}</p></div><span className="text-xs font-bold text-[#52717d]">{item.type}</span><span className="text-xs font-semibold text-[#52717d]">{new Date(item.deadlineDate).toLocaleDateString()}</span><span className={`w-fit rounded-full px-2 py-1 text-xs font-bold ${item.status === "Accepted" ? "bg-[#dff7e8] text-[#258044]" : "bg-[#fff0ea] text-[#d95d3f]"}`}>{item.status}</span></div>)}</div> : <p className="mt-2 text-sm text-[#6c8490]">No application deadlines saved for this day.</p>}</div>}</div>}<div className="mt-8 overflow-hidden rounded-[24px] bg-white card-border"><div className="hidden grid-cols-[1.3fr_.6fr_.6fr_.8fr] gap-4 border-b border-[#edf3f3] px-6 py-4 text-[11px] font-bold uppercase tracking-[.14em] text-[#8aa0a8] sm:grid"><span>Opportunity</span><span>Type</span><span>Deadline</span><span>Status</span></div>{applications.map((a, i) => <div key={a.id ?? `${a.title}-${i}`} onClick={() => setSelectedIndex(i)} className={`grid cursor-pointer gap-3 border-b border-[#edf3f3] px-5 py-5 last:border-0 sm:grid-cols-[1.3fr_.6fr_.6fr_.8fr] sm:items-center sm:gap-4 sm:px-6 ${selectedIndex === i ? "bg-[#f7fafc]" : ""}`}><div><h3 className="text-sm font-bold">{a.title}</h3><p className="mt-1 text-xs text-[#8aa0a8]">{a.org}</p></div><div><span className="text-xs font-bold text-[#52717d]">{a.type}</span></div><div><span className="text-xs font-semibold text-[#52717d]">{a.deadline}</span></div><div className="flex items-center gap-2"><select value={a.status} onClick={e => e.stopPropagation()} onChange={async e => { await onUpdateStatus(a, e.target.value); }} className={`w-fit rounded-full border-0 px-3 py-1.5 text-xs font-bold outline-none ${a.status === "Accepted" ? "bg-[#dff7e8] text-[#258044]" : a.status === "Not started" ? "bg-[#fff0ea] text-[#d95d3f]" : "bg-[#e7efff] text-[#2563eb]"}`}>{statuses.map(status => <option key={status}>{status}</option>)}</select>{a.id && <button aria-label={`Remove ${a.title}`} onClick={async e => { e.stopPropagation(); await onRemoveApplication(a); }} className="text-xs font-bold text-[#8aa0a8] hover:text-[#d95d3f]">Remove</button>}</div></div>)}</div>{editorOpen && <div className="mt-6 rounded-[22px] bg-white p-5 card-border"><div className="flex items-center justify-between"><h2 className="text-xl font-bold">{editingIndex === null ? "Add application" : "Edit application"}</h2><button onClick={() => setEditorOpen(false)} aria-label="Close application editor"><X size={18} /></button></div><div className="mt-4 grid gap-3 sm:grid-cols-2"><input aria-label="Title" value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} placeholder="Title" className="h-11 rounded-xl border border-[#dce9ea] px-3 text-sm" /><input aria-label="Organisation" value={form.organisation} onChange={e => setForm({ ...form, organisation: e.target.value })} placeholder="Organisation" className="h-11 rounded-xl border border-[#dce9ea] px-3 text-sm" /><select aria-label="Type" value={form.type} onChange={e => setForm({ ...form, type: e.target.value })} className="h-11 rounded-xl border border-[#dce9ea] px-3 text-sm"><option>Study</option><option>Work</option><option>Skills</option><option>Business</option><option>Other</option></select><select aria-label="Status" value={form.status} onChange={e => setForm({ ...form, status: e.target.value })} className="h-11 rounded-xl border border-[#dce9ea] px-3 text-sm"><option>Not started</option><option>Applied</option><option>Interview</option><option>Waiting</option><option>Accepted</option><option>Not this time</option><option>Withdrawn</option></select><label className="text-xs font-bold text-[#52717d]">Date applied<input type="date" value={form.dateApplied} onChange={e => setForm({ ...form, dateApplied: e.target.value })} className="mt-1 h-11 w-full rounded-xl border border-[#dce9ea] px-3 text-sm" /></label><label className="text-xs font-bold text-[#52717d]">Deadline date<input type="date" value={form.deadlineDate} onChange={e => setForm({ ...form, deadlineDate: e.target.value })} className="mt-1 h-11 w-full rounded-xl border border-[#dce9ea] px-3 text-sm" /></label><textarea aria-label="Notes" value={form.notes} onChange={e => setForm({ ...form, notes: e.target.value })} placeholder="Notes" className="min-h-[90px] rounded-xl border border-[#dce9ea] p-3 text-sm sm:col-span-2" /></div><div className="mt-4 flex justify-end gap-2"><Button variant="ghost" onClick={() => setEditorOpen(false)}>Cancel</Button><Button onClick={async () => { if (!form.title.trim() || !form.organisation.trim()) return; const payload = { title: form.title.trim(), organisation: form.organisation.trim(), type: form.type as "Study" | "Work" | "Skills" | "Business" | "Other", dateApplied: form.dateApplied ? new Date(form.dateApplied) : undefined, deadlineDate: form.deadlineDate ? new Date(form.deadlineDate) : undefined, status: form.status as any, notes: form.notes }; if (editingIndex === null) await onSaveApplication(payload); else await onEditApplication(editingIndex, payload); setEditorOpen(false); }}>Save application</Button></div></div>}<div className="mt-7 rounded-[22px] bg-[#e8f6f3] p-5 text-sm text-[#52717d]"><strong className="text-[#183b56]">Keep your application notes in one place.</strong> Update a status when you hear back, and PathFinder can help you prepare the next response.<button onClick={async () => { setDraftOpen(!draftOpen); if (!draftOpen) { try { setDraft(await onGenerateDraft(selectedIndex)); } catch {} } }} className="mt-4 flex items-center gap-2 font-bold text-[#0f766e]">{draftOpen ? "Hide application draft" : "Generate application draft"} <ArrowRight size={15} /></button>{draftOpen && <div className="mt-4 rounded-2xl bg-white p-4"><p className="font-bold text-[#183b56]">Starting draft — personalise before sending</p><textarea value={draft} onChange={e => setDraft(e.target.value)} className="mt-3 min-h-[220px] w-full rounded-xl border border-[#dce9ea] p-3 text-sm leading-6 text-[#52717d] outline-none focus:border-[#0d9488]" /><div className="mt-3 flex flex-wrap gap-2"><Button variant="outline" onClick={copyDraft}>Copy</Button><Button variant="outline" onClick={() => window.print()}>Print / PDF</Button><Button variant="outline" onClick={emailDraft}>Email draft</Button></div></div>}</div></div>;
}
'''
s = s[:old_app.start()] + new_app + s[old_app.end():]

# Replace Overview with a compact version that keeps the established editorial style and reads upcoming deadlines.
old_over = re.search(r'function Overview\b.*?(?=\nfunction Deadline)', s, re.S) or re.search(r'function Overview\b.*?(?=function Deadline)', s, re.S)
if not old_over:
    raise SystemExit('Overview function not found')
new_over = r'''function Overview({ name, profileGoal, fitReasons, persistedDirection, onView, profileComplete, onStart, upcomingDeadlines }: { name: string; profileGoal: string; fitReasons: string; persistedDirection: string; onView: (view: string) => void; profileComplete: boolean; onStart: () => void; upcomingDeadlines: any[] }) { const daysUntil = (value: any) => Math.ceil((new Date(value).getTime() - Date.now()) / 86400000); const urgent = upcomingDeadlines.find(item => daysUntil(item.deadlineDate) <= 2); return <div><div className="flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><PathMarker label="Your workspace" /><h1 className="font-display mt-4 text-4xl tracking-[-.04em]">Good to see you, {name}.<br /><span className="text-[#0d9488]">Let’s find your next move.</span></h1><p className="mt-3 text-[#6c8490]">You don’t need the whole map. Just a direction for today.</p></div><Button variant="outline" onClick={() => onView("chat")}><MessageCircle size={17} /> Talk to your guide</Button></div>{upcomingDeadlines.length > 0 && <button onClick={() => onView("applications")} className={`mt-6 flex w-full items-center justify-between gap-4 rounded-2xl border p-4 text-left ${urgent ? "border-[#ffc9bb] bg-[#fff0ea]" : "border-[#dce9ea] bg-white"}`}><div><p className={`text-xs font-bold uppercase tracking-[.14em] ${urgent ? "text-[#d95d3f]" : "text-[#0f766e]"}`}>{urgent ? "Deadline reminder" : "Upcoming deadlines"}</p><p className="mt-1 text-sm font-bold text-[#183b56]">{urgent ? `${urgent.title} is due in ${Math.max(0, daysUntil(urgent.deadlineDate))} day${daysUntil(urgent.deadlineDate) === 1 ? "" : "s"}.` : `${upcomingDeadlines.length} application${upcomingDeadlines.length === 1 ? "" : "s"} due in the next 7 days.`}</p></div><ChevronRight size={18} className={urgent ? "text-[#d95d3f]" : "text-[#0f766e]"} /></button>}<div className="mt-10 grid gap-5 lg:grid-cols-[1.25fr_.75fr]"><div className="rounded-[26px] bg-[#183b56] p-7 text-white shadow-xl shadow-[#183b56]/10"><p className="text-xs font-bold uppercase tracking-[.16em] text-white/45">Recommended direction</p><h2 className="font-display mt-3 text-3xl">{persistedDirection}</h2><p className="mt-3 max-w-[500px] leading-7 text-white/65">{profileGoal ? `Built around what you shared: ${profileGoal}. This is a direction worth exploring with one practical next move.` : "Based on your curiosity and wanting work that creates options, this is a strong direction worth exploring."}</p><div className="mt-7 flex flex-wrap gap-3"><Button variant="light" onClick={() => onView("plan")}>View your pathway <ArrowRight size={16} /></Button><button onClick={() => onView("chat")} className="rounded-full px-4 text-sm font-bold text-white/60 hover:bg-white/10 hover:text-white">Continue chatting</button></div></div><div className="rounded-[26px] bg-white p-7 card-border"><div className="flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-[#8aa0a8]">Your profile</p><h3 className="mt-2 text-lg font-bold">Make your matches sharper</h3></div><div className="flex h-11 w-11 items-center justify-center rounded-2xl bg-[#fff6dc] text-[#bc8610]"><PenLine size={19} /></div></div><p className="mt-4 text-sm leading-6 text-[#6c8490]">Tell us a little more about your context and we’ll make the next suggestions more personal.</p><button onClick={onStart} className="mt-6 flex w-full items-center justify-between rounded-xl bg-[#f7fafc] p-3 text-left text-sm font-bold text-[#0f766e]"><span>{profileComplete ? "Profile saved" : "Complete your profile"}</span>{profileComplete ? <Check size={17} /> : <ChevronRight size={17} />}</button></div></div><div className="mt-10 flex items-end justify-between"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-[#8aa0a8]">Start somewhere</p><h2 className="font-display mt-2 text-3xl tracking-[-.03em]">What are you exploring?</h2></div><button onClick={() => onView("opportunities")} className="hidden text-sm font-bold text-[#0f766e] sm:block">Browse all <ArrowRight size={15} className="ml-1 inline" /></button></div><div className="mt-5 grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{pathways.map(({ icon: Icon, label, copy, tint }) => <button key={label} onClick={() => onView(label === "Study" ? "opportunities" : "chat")} className="group rounded-[20px] bg-white p-5 text-left card-border transition hover:-translate-y-1 hover:shadow-lg"><div className={`flex h-11 w-11 items-center justify-center rounded-xl ${tint === "teal" ? "bg-[#e8f6f3] text-[#0d9488]" : tint === "blue" ? "bg-[#e7efff] text-[#2563eb]" : tint === "amber" ? "bg-[#fff6dc] text-[#bc8610]" : "bg-[#fff0ea] text-[#df6548]"}`}><Icon size={20} /></div><h3 className="mt-5 font-bold text-[#183b56]">{label}</h3><p className="mt-1 text-sm leading-5 text-[#6c8490]">{copy}</p></button>)}</div></div>; }
'''
s = s[:old_over.start()] + new_over + s[old_over.end():]

# Pass live calendar data and invalidate all deadline sources after mutations.
s = s.replace('onEditApplication={async (index, form) => { const item = applications[index]; if (isAuthenticated && item?.id) await updateApplication.mutateAsync({ id: item.id, ...form });', 'deadlineItems={deadlineQuery.data || []} visibleMonth={calendarMonth} onMonthChange={setCalendarMonth} onEditApplication={async (index, form) => { const item = applications[index]; if (isAuthenticated && item?.id) { await updateApplication.mutateAsync({ id: item.id, ...form }); await Promise.all([applicationList.refetch(), deadlineQuery.refetch(), upcomingDeadlineQuery.refetch()]); }')
